#!/usr/bin/env node
// Keeps the boot script and the template's api command byte-equal. Run after editing
// scripts/librechat-boot.sh or any GC source (skills/gc, scripts/gc/seed):
//   node scripts/sync_librechat_boot.js && npx prettier --check public/v4/apps/librechat.yml
// The GC payload block between the BEGIN/END markers is regenerated by
// scripts/gc_skills_bundle.sh; everything else in the boot script is canonical here.
"use strict";
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");
const y = require("yaml");
const ROOT = path.resolve(__dirname, "..");
const BEGIN = "# BEGIN GC PAYLOAD";
const END = "# END GC PAYLOAD";
function die(m) { console.error("sync_librechat_boot: " + m); process.exit(1); }

const bootPath = path.join(ROOT, "scripts/librechat-boot.sh");
const templatePath = path.join(ROOT, "public/v4/apps/librechat.yml");

function splicePayload(boot, payload) {
  const lines = boot.split("\n");
  const begins = lines.map((l, i) => (l.startsWith(BEGIN) ? i : -1)).filter((i) => i >= 0);
  const ends = lines.map((l, i) => (l === END ? i : -1)).filter((i) => i >= 0);
  if (begins.length !== 1 || ends.length !== 1 || ends[0] < begins[0]) die("GC payload markers not found exactly once");
  const before = lines.slice(0, begins[0]).join("\n") + "\n";
  const after = lines.slice(ends[0] + 1).join("\n");
  return before + payload.replace(/\n$/, "") + "\n" + after;
}

const payload = execFileSync("sh", [path.join(ROOT, "scripts/gc_skills_bundle.sh")], { cwd: ROOT, encoding: "utf8" });
const bootCurrent = fs.readFileSync(bootPath, "utf8");
const boot = splicePayload(bootCurrent, payload);
fs.writeFileSync(bootPath, boot);

let t = fs.readFileSync(templatePath, "utf8");
const lines = t.split("\n");
const start = lines.findIndex((l) => l === "        command:");
const vol = lines.findIndex((l) => l === "        volumes:");
if (start < 0 || vol < 0 || vol <= start) die("command/volumes anchors not found");
const block = [
  "        command:",
  "            - 'sh'",
  "            - '-c'",
  "            - " + JSON.stringify(boot),
].join("\n");
lines.splice(start, vol - start, block);
t = lines.join("\n");
fs.writeFileSync(templatePath, t);
const parsed = y.parse(t).services["$$cap_appname"].command;
if (parsed[2] !== boot) die("post-splice byte-equality failed");
console.log("synced, byte-equal: true (" + boot.length + " bytes)");
